    private static IOrderedQueryable<Vehicle> ApplySort(IQueryable<Vehicle> q, string field, bool desc)
    {
        return field switch
        {
            "Id" => desc ? q.OrderByDescending(x => EF.Property<object>(x!, "Id") == null).ThenByDescending(x => EF.Property<object>(x!, "Id")) : q.OrderBy(x => EF.Property<object>(x!, "Id") == null).ThenBy(x => EF.Property<object>(x!, "Id")),
            "Plate" => desc ? q.OrderByDescending(x => EF.Property<object>(x!, "Plate") == null).ThenByDescending(x => EF.Property<object>(x!, "Plate")) : q.OrderBy(x => EF.Property<object>(x!, "Plate") == null).ThenBy(x => EF.Property<object>(x!, "Plate")),
            _ => (IOrderedQueryable<Vehicle>)q.OrderBy(x => 0),
        };
    }

    // #484 — a credential (view.password) is never sent: the key is OMITTED from the body, not nulled.
    // Serializes with the app's configured JSON options, then removes the named keys from each row.
    private sealed class CredentialOmittingResult : IResult
    {
        private readonly object _value;
        private readonly string[] _names;
        private readonly bool _envelope;
        private readonly int _status;
        private readonly string? _location;
        public CredentialOmittingResult(object value, string[] names, bool envelope = false, int status = 200, string? location = null)
        { _value = value; _names = names; _envelope = envelope; _status = status; _location = location; }
        public async System.Threading.Tasks.Task ExecuteAsync(HttpContext http)
        {
            var opts = ((Microsoft.Extensions.Options.IOptions<Microsoft.AspNetCore.Http.Json.JsonOptions>)
                http.RequestServices.GetService(typeof(Microsoft.Extensions.Options.IOptions<Microsoft.AspNetCore.Http.Json.JsonOptions>))!)
                .Value.SerializerOptions;
            var node = System.Text.Json.JsonSerializer.SerializeToNode(_value, _value.GetType(), opts);
            // The keys are the serializer's own for these properties and the envelope's rows (naming policy, rename, attribute), never guessed from names.
            SerializerKeys.StripBody(node, _value, _envelope, opts, _names);
            http.Response.StatusCode = _status;
            if (_location is not null) http.Response.Headers.Location = _location;
            await http.Response.WriteAsJsonAsync(node, opts);
        }
    }
